import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
HEADERS = {
    "Authorization": f"Bearer {os.environ['API_TOKEN']}",
    "Content-Type": "application/json",
}

product = {
    "name": "Newly Designed Product",
    "category": "personal care",
    "ingredients": [],
    "regulatory_standards": [],
    "environmental_assessment_details": {},
}

order_id = os.getenv("ORDER_ID")

validation = requests.post(
    f"{BASE_URL}/regulations/validate",
    headers=HEADERS,
    json={
        "product": product,
        "ingredients": product["ingredients"],
        "standards": product["regulatory_standards"],
    },
)
validation.raise_for_status()
validation_result = validation.json()

sustainability = requests.post(
    f"{BASE_URL}/sustainability-assessment",
    headers=HEADERS,
    json={"product": product},
)
sustainability.raise_for_status()

report_response = requests.get(
    f"{BASE_URL}/reports/compliance",
    headers=HEADERS,
)
report_response.raise_for_status()
report = report_response.json()

def is_compliant(result):
    if isinstance(result, dict):
        for key in ("compliant", "is_compliant", "passed"):
            if key in result:
                return bool(result[key])
        for key in ("status", "compliance_status", "result"):
            value = result.get(key)
            if isinstance(value, str) and value.lower() in {
                "non-compliant", "noncompliant", "failed", "fail"
            }:
                return False
            if isinstance(value, str) and value.lower() in {
                "compliant", "passed", "pass", "approved"
            }:
                return True
    return None

compliant = is_compliant(validation_result)

if compliant is None and isinstance(report, dict):
    products = report.get("products", report.get("items", []))
    if isinstance(products, list):
        for item in products:
            if isinstance(item, dict) and item.get("name") == product["name"]:
                compliant = is_compliant(item)
                break

if compliant is False and order_id:
    response = requests.delete(
        f"{BASE_URL}/orders/{order_id}",
        headers=HEADERS,
    )
    response.raise_for_status()

import os
import requests

BASE_URL = os.environ.get("API_BASE_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({
    "Accept": "application/json",
    "Content-Type": "application/json",
})

# Update the inventory manager's contact information.
contact_response = session.patch(
    f"{BASE_URL}/update_contact_info",
    json={
        "role": "inventory manager",
        "contact_info": {
            "name": os.environ.get("INVENTORY_MANAGER_NAME"),
            "email": os.environ.get("INVENTORY_MANAGER_EMAIL"),
            "phone": os.environ.get("INVENTORY_MANAGER_PHONE"),
        },
    },
)
contact_response.raise_for_status()

# Submit responses to the questionnaire.
questionnaire_id = os.environ["QUESTIONNAIRE_ID"]
patient_id = os.environ["PATIENT_ID"]
responses_response = session.post(
    f"{BASE_URL}/responses",
    json={
        "questionnaire_id": questionnaire_id,
        "patient_id": patient_id,
        "responses": [],
    },
)
responses_response.raise_for_status()

# Retrieve medications below the low-stock threshold.
low_stock_response = session.get(f"{BASE_URL}/inventory/low-stock")
low_stock_response.raise_for_status()
low_stock_data = low_stock_response.json()
medications = low_stock_data if isinstance(low_stock_data, list) else low_stock_data.get("medications", [])

# Create a replenishment order for the low-stock medications.
if medications:
    order_response = session.post(
        f"{BASE_URL}/orders/new",
        json={
            "medications": [
                {
                    "medication_id": medication.get("medicationId", medication.get("id")),
                    "quantity": medication.get("reorder_quantity", medication.get("quantity_to_reorder")),
                }
                for medication in medications
            ]
        },
    )
    order_response.raise_for_status()

# Remove medications explicitly marked for removal.
for medication in medications:
    if medication.get("marked_for_removal") is True:
        medication_id = medication.get("medicationId", medication.get("id"))
        if medication_id is None:
            continue
        remove_response = session.delete(
            f"{BASE_URL}/inventory/remove/{medication_id}"
        )
        remove_response.raise_for_status()

