import requests

BASE_URL = "https://api.socbench.example"

license_data = {
    "name": "Financial Application",
    "licenseType": "perpetual",
}
license_response = requests.post(
    f"{BASE_URL}/software/licenses",
    json=license_data,
)
license_response.raise_for_status()

alert_response = requests.post(
    f"{BASE_URL}/alert",
    json={
        "title": "Financial application license configured",
        "description": "The perpetual license configuration is ready for compliance validation.",
        "severity": "medium",
        "source": "software-license-management",
    },
)
alert_response.raise_for_status()
alert_id = alert_response.json().get("alertId")

# Configure an alert for software usage incidents.
requests.post(
    f"{BASE_URL}/alerts",
    json={
        "event": "software_usage_incident",
        "notificationMethod": "email",
        "recipients": ["team@example.com"],
    },
).raise_for_status()

# Retrieve available rules to review current transformation and analytical rules.
rules_response = requests.get(f"{BASE_URL}/config/rules")
rules_response.raise_for_status()
rules = rules_response.json()

# The documented API provides rule creation and update, but no transformation execution,
# workflow listing, or rule deletion endpoint. Use an existing rule to update its
# definition for license validation where possible.
license_rule = next(
    (
        rule for rule in rules
        if "license" in rule.get("ruleName", "").lower()
        and rule.get("ruleID")
    ),
    None,
)
if license_rule:
    requests.put(
        f"{BASE_URL}/config/rules/{license_rule['ruleID']}",
        json={
            "ruleName": license_rule["ruleName"],
            "ruleDefinition": {
                "purpose": "Validate perpetual financial application license configuration",
                "complianceCheck": True,
            },
        },
    ).raise_for_status()

# Confirm the created alert can be retrieved.
if alert_id:
    requests.get(f"{BASE_URL}/alert/{alert_id}").raise_for_status()

# Refresh the rules list for review.
requests.get(f"{BASE_URL}/config/rules").raise_for_status()
